package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct { // 01 LOAN-REC, 21 bytes
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsTotal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(11)V99 len=13 = 0
var WsCount int64 = 0 // PIC 9(5) len=5 = 0
var WsPrinEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var curLoan LoanRec
var fileScanner *bufio.Scanner

func parseScaled(s string, scale int32) decimal.Decimal {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else if c == ' ' {
			d = 0
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return decimal.New(n, -scale)
}

func parseInt(s string) int64 {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else if c == ' ' {
			d = 0
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return n
}

func fitDecimal(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	scaled := d.Shift(scale).Truncate(0)
	iv := scaled.IntPart()
	total := intDigits + int(scale)
	var mod int64 = 1
	for i := 0; i < total; i++ {
		mod *= 10
	}
	ivMod := iv % mod
	return decimal.New(ivMod, -scale)
}

func formatEdited(val decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	var intPat, fracPat string
	hasDot := dotIdx >= 0
	if hasDot {
		intPat = pic[:dotIdx]
		fracPat = pic[dotIdx+1:]
	} else {
		intPat = pic
		fracPat = ""
	}
	intSlots := 0
	for i := 0; i < len(intPat); i++ {
		if intPat[i] == 'Z' || intPat[i] == '9' {
			intSlots++
		}
	}
	fracSlots := 0
	for i := 0; i < len(fracPat); i++ {
		if fracPat[i] == 'Z' || fracPat[i] == '9' {
			fracSlots++
		}
	}
	t := val.Truncate(int32(fracSlots))
	scaled := t.Shift(int32(fracSlots)).Truncate(0).IntPart()
	var powFrac int64 = 1
	for i := 0; i < fracSlots; i++ {
		powFrac *= 10
	}
	var intPart, fracPart int64
	if fracSlots > 0 {
		intPart = scaled / powFrac
		fracPart = scaled % powFrac
	} else {
		intPart = scaled
		fracPart = 0
	}
	var powInt int64 = 1
	for i := 0; i < intSlots; i++ {
		powInt *= 10
	}
	intMod := intPart % powInt
	intAbs := intMod
	if intAbs < 0 {
		intAbs = -intAbs
	}
	fracAbs := fracPart
	if fracAbs < 0 {
		fracAbs = -fracAbs
	}
	intDigits := make([]int64, intSlots)
	tmp := intAbs
	for i := intSlots - 1; i >= 0; i-- {
		intDigits[i] = tmp % 10
		tmp /= 10
	}
	var sb strings.Builder
	suppressed := true
	digitIdx := 0
	for i := 0; i < len(intPat); i++ {
		c := intPat[i]
		if c == 'Z' || c == '9' {
			d := intDigits[digitIdx]
			var ch byte
			if c == 'Z' && suppressed && d == 0 {
				ch = ' '
			} else {
				ch = byte('0' + d)
				suppressed = false
			}
			sb.WriteByte(ch)
			digitIdx++
		} else if c == ',' {
			if suppressed {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(',')
			}
		} else {
			sb.WriteByte(c)
		}
	}
	if hasDot {
		sb.WriteByte('.')
		fracDigits := make([]int64, fracSlots)
		tmp2 := fracAbs
		for i := fracSlots - 1; i >= 0; i-- {
			fracDigits[i] = tmp2 % 10
			tmp2 /= 10
		}
		fIdx := 0
		for i := 0; i < len(fracPat); i++ {
			c := fracPat[i]
			if c == 'Z' || c == '9' {
				d := fracDigits[fIdx]
				sb.WriteByte(byte('0' + d))
				fIdx++
			} else {
				sb.WriteByte(c)
			}
		}
	}
	return sb.String()
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	sc := bufio.NewScanner(f)
	buf := make([]byte, 0, 64*1024)
	sc.Buffer(buf, 10*1024*1024)
	fileScanner = sc
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	if err := fileScanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		f.Close()
		os.Exit(1)
	}
	f.Close()
	SummaryPara()
}

func ReadPara() {
	if fileScanner.Scan() {
		line := fileScanner.Text()
		if len(line) < 21 {
			line = line + strings.Repeat(" ", 21-len(line))
		} else if len(line) > 21 {
			line = line[:21]
		}
		curLoan.LrAcct = line[0:6]
		curLoan.LrPrincipal = parseScaled(line[6:15], 2)
		curLoan.LrRate = parseScaled(line[15:19], 2)
		curLoan.LrYears = parseInt(line[19:21])
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	raw := curLoan.LrPrincipal.Mul(curLoan.LrRate).Mul(decimal.NewFromInt(curLoan.LrYears)).Shift(-2)
	rounded := raw.Round(2)
	WsInterest = fitDecimal(rounded, 9, 2)
	newTotal := WsTotal.Add(WsInterest).Truncate(2)
	WsTotal = fitDecimal(newTotal, 11, 2)
	WsCount = (WsCount + 1) % 100000
	WsPrinEd = formatEdited(curLoan.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	fmt.Println(curLoan.LrAcct + " " + WsPrinEd + " " + WsIntEd)
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsCount)
	fmt.Println("RECORDS: " + countStr)
	fmt.Println("TOTAL INTEREST: " + WsTotalEd)
}

func main() {
	MainPara()
}
